package org.apache.lucene.geo;

public class Dbg {
  public static void main(String[] args) {
    int base = Integer.MAX_VALUE;
    Polygon poly =
        new Polygon(
            new double[] {
              GeoEncodingUtils.decodeLatitude(base - 3),
              GeoEncodingUtils.decodeLatitude(base - 3),
              GeoEncodingUtils.decodeLatitude(base),
              GeoEncodingUtils.decodeLatitude(base),
              GeoEncodingUtils.decodeLatitude(base - 3)
            },
            new double[] {
              GeoEncodingUtils.decodeLongitude(base - 3),
              GeoEncodingUtils.decodeLongitude(base),
              GeoEncodingUtils.decodeLongitude(base),
              GeoEncodingUtils.decodeLongitude(base - 3),
              GeoEncodingUtils.decodeLongitude(base - 3)
            });
    Polygon2D c = (Polygon2D) LatLonGeometry.create(poly);
    int lat = base - 2;
    int lon = base - 2;
    double decodedLat = lat * (1 / ((0x1L << 32) / 180.0D));
    double decodedLon = lon * (1 / ((0x1L << 32) / 360.0D));
    System.out.println("contains=" + c.contains(decodedLon, decodedLat));
    System.out.println("tree.contains=" + c.tree.contains(decodedLon, decodedLat));
    System.out.println("minX=" + c.getMinX() + " maxX=" + c.getMaxX());
    System.out.println("minY=" + c.getMinY() + " maxY=" + c.getMaxY());
    System.out.println("decoded=" + decodedLon + "," + decodedLat);
    walk(c.tree, decodedLon, decodedLat, 0);
  }

  static void walk(EdgeTree n, double x, double y, int depth) {
    if (n == null) return;
    System.out.printf(
        "%sedge %s x1=%.17g y1=%.17g x2=%.17g y2=%.17g low=%.17g max=%.17g%n",
        "  ".repeat(depth), n, n.x1, n.y1, n.x2, n.y2, n.low, n.max);
    walk(n.left, x, y, depth + 1);
    walk(n.right, x, y, depth + 1);
  }
}

